<?php require __DIR__.'/../config/database.php';require __DIR__.'/../config/auth.php';require_role(['staff']);require __DIR__.'/../config/smart_ops.php';require_work_checkin($pdo);$uid=$_SESSION['user']['id'];$st=$pdo->prepare("SELECT * FROM staff WHERE user_id=?");$st->execute([$uid]);$me=$st->fetch();if(!$me||!in_array($me['staff_type'],['delivery_man','multipurpose'],true))die('Delivery access is only for Delivery or Multipurpose staff.');$msg=$err='';
try{if(isset($_POST['accept'])){$oid=(int)$_POST['order_id'];$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM shop_orders WHERE id=? FOR UPDATE");$q->execute([$oid]);$o=$q->fetch();if(!$o||$o['assigned_staff_id'])throw new Exception('This order has already been assigned.');if(!in_array($o['status'],['confirmed','preparing','ready_for_delivery'],true))throw new Exception('Order is not ready for delivery acceptance.');$pdo->prepare("UPDATE shop_orders SET assigned_staff_id=?,status='out_for_delivery',delivery_accepted_at=NOW() WHERE id=?")->execute([$me['id'],$oid]);$pdo->prepare("INSERT INTO shop_order_status_log(order_id,status,note,changed_by) VALUES(?,'out_for_delivery','Accepted by delivery staff',?)")->execute([$oid,$uid]);$pdo->commit();$msg='Delivery accepted.';}if(isset($_POST['start'])){$oid=(int)$_POST['order_id'];$pdo->prepare("UPDATE shop_orders SET status='out_for_delivery',delivery_accepted_at=COALESCE(delivery_accepted_at,NOW()) WHERE id=? AND assigned_staff_id=?")->execute([$oid,$me['id']]);$msg='Delivery started.';}if(isset($_POST['delivered'])){$oid=(int)$_POST['order_id'];$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM shop_orders WHERE id=? AND assigned_staff_id=? FOR UPDATE");$q->execute([$oid,$me['id']]);$o=$q->fetch();if(!$o)throw new Exception('Order not found.');$pdo->prepare("UPDATE shop_orders SET status='delivered',delivered_at=NOW() WHERE id=?")->execute([$oid]);$pdo->prepare("INSERT INTO shop_order_status_log(order_id,status,note,changed_by) VALUES(?,'delivered','Delivered to customer',?)")->execute([$oid,$uid]);$pdo->prepare("INSERT INTO income(farm_id,source,amount,income_date,note,created_by) VALUES(NULL,'Shop Sale',?,CURDATE(),?,?)")->execute([$o['total_amount'],'Delivered order #'.$oid,$uid]);$pdo->prepare("INSERT IGNORE INTO delivery_earnings(staff_user_id,order_id,amount,status) VALUES(?,?,50,'credited')")->execute([$uid,$oid]);$pdo->commit();$msg='Order marked delivered and sale recorded as income.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}
$mine=$pdo->prepare("SELECT o.*,u.name customer_name FROM shop_orders o JOIN users u ON u.id=o.customer_user_id WHERE o.assigned_staff_id=? AND o.status NOT IN('delivered','cancelled') ORDER BY o.id DESC");$mine->execute([$me['id']]);$mine=$mine->fetchAll();$open=$pdo->query("SELECT o.*,u.name customer_name FROM shop_orders o JOIN users u ON u.id=o.customer_user_id WHERE o.assigned_staff_id IS NULL AND o.status IN('confirmed','preparing','ready_for_delivery') ORDER BY o.id")->fetchAll();$page_title='My Deliveries';require __DIR__.'/../partials/header.php';?>
<div class="container py-4"><div class="page-head"><div><span class="eyebrow green">DELIVERY</span><h2>My Delivery Board</h2><p>Accept available orders or complete deliveries assigned by your Manager.</p></div><a class="btn btn-outline-success" href="<?=url_path('staff/dashboard.php')?>">Dashboard</a></div><?php if($msg):?><div class="alert alert-success"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=htmlspecialchars($err)?></div><?php endif;?><h5 class="mt-4">Assigned to me</h5><div class="row g-3"><?php foreach($mine as $o):?><div class="col-md-6"><div class="cardx p-3"><div class="d-flex justify-content-between"><b>Order #<?=$o['id']?></b><span class="badge-soft"><?=str_replace('_',' ',$o['status'])?></span></div><h5 class="mt-3"><?=htmlspecialchars($o['customer_name'])?></h5><div class="delivery-pay">Delivery earning after completion: <b>৳50</b></div><p class="text-muted mb-2"><?=htmlspecialchars($o['delivery_address'])?><br><?=htmlspecialchars($o['phone'])?><?php if(!empty($o['alternate_phone'])):?><br>Alt: <?=htmlspecialchars($o['alternate_phone'])?><?php endif;?><br><b><?=htmlspecialchars(str_replace('_',' ',$o['delivery_method']??'local_delivery'))?></b></p><form method="post" class="d-flex gap-2"><input type="hidden" name="order_id" value="<?=$o['id']?>"><?php if($o['status']!=='out_for_delivery'):?><button class="btn btn-outline-success" name="start">Start Delivery</button><?php endif;?><button class="btn btn-success" name="delivered">Mark Delivered</button></form></div></div><?php endforeach;?></div><h5 class="mt-5">Available to accept</h5><div class="row g-3"><?php foreach($open as $o):?><div class="col-md-6"><div class="cardx p-3"><b>Order #<?=$o['id']?> · <?=htmlspecialchars($o['customer_name'])?></b><p class="text-muted mt-2"><?=htmlspecialchars($o['delivery_address'])?></p><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><button class="btn btn-success" name="accept">Accept Delivery</button></form></div></div><?php endforeach;?><?php if(!$open):?><div class="col-12 text-muted">No unassigned orders available right now.</div><?php endif;?></div></div>
